/** Every entry in the codex, in one flat array. */
export const CODEX = [
  SUN,
  ...PLANETS,
  ...DWARFS,
  ...MOONS,
  ...SMALL_BODIES,
  ...DEEP_SKY,
  ...MISSIONS,
  ...TECH,
  ...PEOPLE,
  ...THEORIES,
  ...AGENCIES,
].map((entry) => ({
  ...entry,
  search: [entry.name, entry.cat, entry.era, entry.who, entry.when, ...(entry.facts || []), entry.line]
    .join(" ")
    .toLowerCase(),
}));

export const byId = (id) => CODEX.find((e) => e.id === id) || null;

/** Fuzzy-ish search: name matches rank above fact matches. */
export function searchCodex(query, { cat = "all", era = "all" } = {}) {
  const q = query.trim().toLowerCase();
  const words = q.split(/\s+/).filter(Boolean);
  return CODEX.filter((e) => (cat === "all" || e.cat === cat) && (era === "all" || e.era === era))
    .map((e) => {
      if (!words.length) return { e, score: 1 };
      let score = 0;
      for (const w of words) {
        if (e.name.toLowerCase().includes(w)) score += 10;
        if (e.id.includes(w)) score += 6;
        if (e.cat.includes(w)) score += 3;
        if (e.search.includes(w)) score += 1;
      }
      return { e, score };
    })
    .filter((r) => r.score > 0)
    .sort((a, b) => b.score - a.score || a.e.name.localeCompare(b.e.name))
    .map((r) => r.e);
}

export const CODEX_COUNT = CODEX.length;
